    /// <summary>Maps the common CRUD operations (GetById / GetAll / Insert / Update / Delete / Save / SaveMany).</summary>
    public static void MapCrud<TEntity, TKey, TRepository>(
        RouteGroupBuilder group,
        string entityRoute
    )
        where TEntity : EntityBase, new()
        where TRepository : notnull, IRemoteRepository<TEntity, TKey>
    {
        group.MapPost(
            $"{entityRoute}/GetById",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteIdRequest<TKey>>(context).ConfigureAwait(false);
                        return (object?)
                            await Repository<TRepository>(context)
                                .GetByIdAsync(
                                    Required(request.Id, "Id"),
                                    context.RequestAborted
                                ).ConfigureAwait(false);
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/GetAll",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                        (object?)
                            await Repository<TRepository>(context)
                                .GetAllAsync(context.RequestAborted).ConfigureAwait(false)
                )
        );
        group.MapPost(
            $"{entityRoute}/Insert",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteEntityRequest<TEntity>>(context).ConfigureAwait(false);
                        var entity = Required(request.Entity, "Entity");
                        await Repository<TRepository>(context)
                            .InsertAsync(entity, context.RequestAborted).ConfigureAwait(false);
                        // The insert leaves the newly assigned version on the entity, which the client writes back
                        return (object?)
                            new RemoteInsertResult(RemoteEntityGraph.ReadRowVersion(entity));
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/Update",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteUpdateRequest<TEntity>>(context).ConfigureAwait(false);
                        var entity = Required(request.Entity, "Entity");
                        var updated = await Repository<TRepository>(context)
                            .UpdateAsync(
                                entity,
                                ValidatedMode(request.Mode),
                                context.RequestAborted
                            ).ConfigureAwait(false);
                        // A successful update leaves the newly assigned version on the entity, which the client writes back
                        return (object?)
                            new RemoteUpdateResult(
                                updated,
                                updated ? RemoteEntityGraph.ReadRowVersion(entity) : null
                            );
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/Delete",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteIdRequest<TKey>>(context).ConfigureAwait(false);
                        return (object?)
                            await Repository<TRepository>(context)
                                .DeleteAsync(
                                    Required(request.Id, "Id"),
                                    context.RequestAborted
                                ).ConfigureAwait(false);
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/Save",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteSaveRequest<TEntity>>(context).ConfigureAwait(false);
                        var entity = Required(request.Entity, "Entity");
                        var affected = await Repository<TRepository>(context)
                            .SaveAsync(
                                entity,
                                request.CascadeSave,
                                request.CascadeDelete,
                                request.InsertWhenUpdateMissing,
                                ValidatedMode(request.Mode),
                                context.RequestAborted
                            ).ConfigureAwait(false);
                        return (object?)
                            new RemoteSaveResult(
                                affected,
                                CollectRowVersions([entity], request.CascadeSave),
                                CollectSkipped([entity], request.CascadeSave)
                            );
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/SaveMany",
            (HttpContext context) =>
                ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await ReadRequestAsync<RemoteSaveManyRequest<TEntity>>(
                            context
                        ).ConfigureAwait(false);
                        var entities = Required(request.Entities, "Entities");
                        var affected = await Repository<TRepository>(context)
                            .SaveAsync(
                                entities,
                                request.CascadeSave,
                                request.CascadeDelete,
                                request.InsertWhenUpdateMissing,
                                ValidatedMode(request.Mode),
                                context.RequestAborted
                            ).ConfigureAwait(false);
                        return (object?)
                            new RemoteSaveResult(
                                affected,
                                CollectRowVersions(entities, request.CascadeSave),
                                CollectSkipped(entities, request.CascadeSave)
                            );
                    }
                )
        );
    }

    /// <summary>
    /// Collects the row versions a completed save assigned across the saved graphs, so that the client can write them back
    /// onto its own entities.
    /// </summary>
    /// <remarks>
    /// The traversal is the server-side counterpart of the client's <c>AcceptChanges</c>: both walk the same
    /// [NavigationReference(Cascade=true)] child navigations (<c>RemoteEntityGraph.CascadeNavigations</c>) and identify an
    /// entity the same way, so every collected entry lands on the matching local entity. Backends that assign no versions -
    /// a dialect without a rowversion type, or a diagram whose tables carry no such column - simply yield an empty list.
    /// </remarks>
    public static List<RemoteRowVersionEntry> CollectRowVersions<TEntity>(
        IEnumerable<TEntity> entities,
        bool cascade
    )
        where TEntity : EntityBase
    {
        var rowVersions = new List<RemoteRowVersionEntry>();

        foreach (var entity in entities)
        {
            // A null element is filtered out by the save itself, so it is passed over here as well
            if (entity is not null)
            {
                RemoteEntityGraph.CollectRowVersions(entity, cascade, rowVersions);
            }
        }

        return rowVersions;
    }

    /// <summary>
    /// Collects the rows a save hook's Before skipped, so that the client can leave their RowState untouched instead of
    /// finalizing them to Unchanged.
    /// </summary>
    /// <remarks>
    /// <para>
    /// A completed save has already finalized every row it operated on (<c>EntityGraphSaver.AcceptChanges</c> leaves the
    /// skipped ones alone), so a row that still carries changes is exactly a row the hook skipped - no separate bookkeeping
    /// has to travel from the repository to here. Deleted rows are left out because the client leaves a removed entity
    /// untouched in either case.
    /// </para>
    /// <para>
    /// The traversal and the identity of a row are shared with the row version table, so the same constraint applies: when a
    /// graph contains the same (type, key) twice, the entries collapse onto one entity on the client side.
    /// </para>
    /// <para>
    /// The list is part of the wire contract, which is not promised to stay compatible across QuickER versions while the tool
    /// is at 0.x. A client generated before this field existed ignores it and finalizes the rows the hook declined, so the
    /// skip stays a server-side fact and never reaches the caller. Nothing announces that mismatch: regenerate the client and
    /// the server from the same diagram and deploy them together.
    /// </para>
    /// </remarks>
    public static List<RemoteEntityRef> CollectSkipped<TEntity>(
        IEnumerable<TEntity> entities,
        bool cascade
    )
        where TEntity : EntityBase
    {
        var skipped = new List<RemoteEntityRef>();

        foreach (var entity in entities)
        {
            // A null element is filtered out by the save itself, so it is passed over here as well
            if (entity is not null)
            {
                RemoteEntityGraph.CollectSkipped(entity, cascade, skipped);
            }
        }

        return skipped;
    }
}

/// <summary>
/// Marks a failure to interpret the request itself (the JSON body, a required field it omitted, or the <c>?id=</c>
/// key). The request never reached
/// the repository, so it is a fault in what the client sent rather than a server-side error: it is answered with
/// HTTP 400 and a <see cref="RemoteError"/> of type "BadRequest", and neither the server-side logging nor the
/// <c>OnServerError</c> hook - both reserved for HTTP 500 - is invoked.
/// </summary>
internal sealed class RemoteBadRequestException : Exception
{
    /// <summary>Initializes a new instance with the message reported to the client.</summary>
    public RemoteBadRequestException(string message)
        : base(message) { }

    /// <summary>Initializes a new instance with the message reported to the client and the underlying failure.</summary>
    public RemoteBadRequestException(string message, Exception innerException)
        : base(message, innerException) { }
}

/// <summary>Endpoint metadata recording how the group was mapped: whether its 500 responses expose server-side error details, and what to raise when one occurs.</summary>
/// <remarks>
/// Attached to the group by <c>MapGeneratedRemoteEndpoints</c> so that the policy reaches the wrappers through the
/// matched endpoint instead of through every handler signature. Storing it per endpoint also keeps two groups mapped
/// in the same process - say a public one and an internal one - independent of each other. The hook travels the same
/// way because a partial method cannot be called across assemblies: the generated part passes its own wrapper, which
/// already isolates a failure inside the user's implementation.
/// </remarks>
internal sealed class RemoteErrorDetailPolicy(
    bool expose,
    Action<HttpContext, Exception>? onServerError
)
{
    /// <summary>Gets a value indicating whether the server-side exception message is reported to the client.</summary>
    public bool Expose { get; } = expose;

    /// <summary>Gets the extension hook raised - after the built-in logging - whenever an endpoint of the group responds with HTTP 500 (null when the group was mapped without one).</summary>
    public Action<HttpContext, Exception>? OnServerError { get; } = onServerError;
}

/// <summary>Endpoint metadata that lifts the request size limit for the binary PUT (attached only when the group opted in to unbounded uploads).</summary>
/// <remarks>
/// It is attached only when the group was mapped with <c>allowUnboundedUploads: true</c>; without it the host's own
/// limit - 30 MB under Kestrel's defaults - applies and a larger upload is rejected with HTTP 413. Because an endpoint
/// that accepts a body of any size is a denial-of-service surface, combining the opt-in with authorization
/// (<c>MapGeneratedRemoteEndpoints(...).RequireAuthorization()</c>) is recommended.
/// To set a limit of a different size, override the whole group via the returned <see cref="RouteGroupBuilder"/>.
/// </remarks>
internal sealed class DisableRequestBodySizeLimit : IRequestSizeLimitMetadata
{
    /// <summary>Shared instance for attaching the metadata.</summary>
    public static readonly DisableRequestBodySizeLimit Instance = new();

    /// <summary>Represents no limit (<c>null</c>).</summary>
    public long? MaxRequestBodySize => null;
}

/// <summary>
/// Wrapper stream that defers the response start (status resolution and header transmission) until the first write
/// during a GET download. If no write ever occurs, the caller can switch to 404 (the read function's contract is to
/// write nothing when it returns false).
/// </summary>
internal sealed class DeferredOctetStreamBody(HttpResponse response) : Stream
{
    private bool _started;

    /// <summary>Sets the Content-Type if the response has not started yet (the actual header transmission happens on the first body write).</summary>
    public void EnsureStarted()
    {
        if (_started)
        {
            return;
        }

        _started = true;
        response.ContentType = "application/octet-stream";
    }

    /// <inheritdoc />
    public override async ValueTask WriteAsync(
        ReadOnlyMemory<byte> buffer,
        CancellationToken cancellationToken = default
    )
    {
        EnsureStarted();
        await response.Body.WriteAsync(buffer, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public override Task WriteAsync(
        byte[] buffer,
        int offset,
        int count,
        CancellationToken cancellationToken
    ) => WriteAsync(buffer.AsMemory(offset, count), cancellationToken).AsTask();

    /// <inheritdoc />
    public override void Write(byte[] buffer, int offset, int count) =>
        WriteAsync(buffer.AsMemory(offset, count)).AsTask().GetAwaiter().GetResult();

    /// <inheritdoc />
    public override async Task FlushAsync(CancellationToken cancellationToken)
    {
        EnsureStarted();
        await response.Body.FlushAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public override void Flush() { }

    /// <inheritdoc />
    public override bool CanWrite => true;
    /// <inheritdoc />
    public override bool CanRead => false;
    /// <inheritdoc />
    public override bool CanSeek => false;
    /// <inheritdoc />
    public override long Length => throw new NotSupportedException();
    /// <inheritdoc />
    public override long Position
    {
        get => throw new NotSupportedException();
        set => throw new NotSupportedException();
    }

    /// <inheritdoc />
    public override int Read(byte[] buffer, int offset, int count) =>
        throw new NotSupportedException();

    /// <inheritdoc />
    public override long Seek(long offset, SeekOrigin origin) =>
        throw new NotSupportedException();

    /// <inheritdoc />
    public override void SetLength(long value) => throw new NotSupportedException();
}

/// <summary>
/// Endpoint mapping that exposes the generated remote surface (I{Entity}RemoteRepository) as an ASP.NET Core Minimal API.
/// </summary>
/// <remarks>
/// <para>
/// Place this file in a project that has the ASP.NET Core FrameworkReference (<c>Microsoft.AspNetCore.App</c>);
/// no extra configuration is needed when the SDK is <c>Microsoft.NET.Sdk.Web</c>. Register the concrete repositories
/// (<c>AddGeneratedSqlServerRepositories</c> / <c>AddGeneratedEfCoreRepositories</c>, etc.) in the server-side DI container.
/// </para>
/// <para>
/// Each operation is exposed as <c>POST {prefix}/{entity}/{operation}</c> (JSON body). Apply cross-cutting concerns
/// such as authorization to the returned <see cref="RouteGroupBuilder"/>
/// (for example <c>app.MapGeneratedRemoteEndpoints().RequireAuthorization()</c>).
/// Exceptions are converted to structured JSON (RemoteError): <see cref="SaveConflictException"/> maps to 409 and
/// an unhandled failure to 500, and the client (Http{Entity}RemoteRepository) restores the original exception type.
/// </para>
/// <para>
/// Until authorization is supplied, every endpoint is open to anyone who can reach it, and the policy belongs on the
/// group as a whole rather than on hand-picked endpoints. <c>Save</c> and <c>SaveMany</c> are as powerful as
/// <c>Delete</c>: a graph whose nodes carry <c>RowState.Removed</c> deletes those rows, so a policy that guards
/// <c>Delete</c> while leaving <c>Save</c> open guards nothing. The same holds for the payloads in general - the wire
/// format accepts every column an entity has, the primary key included - so authorization is the only thing standing
/// between a caller and any row it can name. Apply it in one line with
/// <c>app.MapGeneratedRemoteEndpoints().RequireAuthorization()</c>.
/// </para>
/// <para>
/// An unhandled failure (500) does not report what went wrong to the client unless
/// <c>exposeErrorDetails</c> is turned on: by default the body carries a fixed generic message plus the
/// correlation id of the request, while the full exception - stack trace included - goes to the server log under that
/// same id. The classified responses (400 and 409) are unaffected, because their messages are written here rather than
/// taken from an internal failure, and the conflict details a 409 carries are what a retry loop is built on.
/// </para>
/// <para>
/// A request that cannot be interpreted at all - a malformed or empty JSON body, a non-JSON content type, a type
/// mismatch, a value that fails value-object validation, a body that omits a required field such as the entity, an
/// undefined <see cref="ConcurrencyMode"/> value, or a
/// missing/malformed <c>?id=</c> key - is a fault in what the client sent, so it is answered with HTTP 400
/// (RemoteError of type "BadRequest") instead of 500. A request
/// rejected by the server infrastructure (<see cref="BadHttpRequestException"/>, for example when the request body
/// size limit is exceeded) keeps the status code it carries, such as 413.
/// </para>
/// <para>
/// The request handling itself - reading the body, classifying exceptions, writing the response - lives in
/// <c>RemoteServerEngine</c>, which is fixed code shared by every diagram. What remains here is the mapping entry
/// point and the endpoints of each entity.
/// </para>
/// <para>
/// The wire format these endpoints speak is not promised to stay compatible across QuickER versions while the tool is
/// at 0.x, and nothing on the wire announces a mismatch, so regenerate the client and the server from the same diagram
/// and deploy them together.
/// </para>
/// <para>
/// The class is <c>partial</c> so additional endpoints or helpers can live alongside the generated ones,
/// and the <c>OnServerError</c> partial method can be implemented to add custom handling (notifications,
/// metrics, extra logging) whenever an endpoint responds with HTTP 500.
/// </para>
/// </remarks>
public static partial class GeneratedRemoteEndpoints
{
    /// <summary>Maps every remote-surface endpoint under the given prefix (defaults to <see cref="RemotePaths.DefaultPrefix"/>).</summary>
    /// <remarks>
    /// <para>
    /// Until authorization is applied to the returned group, every endpoint mapped here is open to anyone who can reach it,
    /// and the wire format accepts any row a caller can name - <c>Save</c> deletes rows just as <c>Delete</c> does, so
    /// guarding one operation and not the other guards nothing. Apply it to the group as a whole with
    /// <c>app.MapGeneratedRemoteEndpoints().RequireAuthorization()</c> (see the remarks on
    /// <see cref="GeneratedRemoteEndpoints"/> for the full reasoning).
    /// </para>
    /// <para>
    /// The group also carries a liveness endpoint, <c>GET {prefix}/health</c>, which answers 200 with an empty body
    /// once the server is listening. It is a member of the group like any other endpoint, so authorization applied to
    /// the group covers it as well; a probe that has to stay anonymous can be given its own route mapped outside the
    /// group instead.
    /// </para>
    /// </remarks>
    /// <param name="endpoints">The mapping target (for example a <c>WebApplication</c>).</param>
    /// <param name="prefix">The route prefix for the endpoint group.</param>
    /// <param name="exposeErrorDetails">
    /// Whether an HTTP 500 response reports the server-side exception message to the client. It is off by default, which
    /// keeps internal details - table and column names, connection strings, file paths - from crossing the trust
    /// boundary: the client is given a fixed generic message plus the correlation id of the request instead. Because it
    /// is an argument rather than a generation-time option, the same generated code covers both sides of the trade-off;
    /// pass <c>app.Environment.IsDevelopment()</c> to read the real message while developing and hide it in production.
    /// Server-side logging and the <c>OnServerError</c> hook always receive the full exception either way, and the
    /// classified responses (400 and 409) are not affected by this switch.
    /// </param>
    /// <param name="allowUnboundedUploads">
    /// Whether the binary column upload endpoints (<c>PUT {prefix}/{entity}/{column}</c>) are exempt from the host's
    /// request body size limit. It is off by default, so an upload larger than the limit the host applies - 30 MB under
    /// Kestrel's defaults - is rejected with HTTP 413 like any other request. Turn it on to stream blobs of arbitrary
    /// size, and pair it with authorization (<c>MapGeneratedRemoteEndpoints(...).RequireAuthorization()</c>): an
    /// endpoint that accepts a body of any size is a denial-of-service surface. Only these endpoints are affected; a
    /// different limit can be set on the returned group instead.
    /// </param>
    /// <returns>The endpoint group, to which authorization and similar concerns can be applied.</returns>
    public static RouteGroupBuilder MapGeneratedRemoteEndpoints(
        this IEndpointRouteBuilder endpoints,
        string prefix = RemotePaths.DefaultPrefix,
        bool exposeErrorDetails = false,
        bool allowUnboundedUploads = false
    )
    {
        ArgumentNullException.ThrowIfNull(endpoints);

        var group = endpoints.MapGroup(prefix);

        // The policy travels as endpoint metadata rather than as a handler argument: every 500 is written by one of the
        // wrappers in the engine, which already have the HttpContext, so no handler signature has to change to carry it.
        // The hook goes along the same way, as the engine cannot call a partial method declared here
        group.WithMetadata(new RemoteErrorDetailPolicy(exposeErrorDetails, RaiseServerError));

        // Liveness: the client's PingAsync polls this while waiting for the server to come up, so it must not touch
        // the database - a 200 states that the process is listening and the endpoints are mapped, nothing more
        group.MapGet(RemotePaths.HealthRoute, () => Results.Ok());
        MapSyncOrderEndpoints(group, allowUnboundedUploads);
        MapSyncOrderLineEndpoints(group);
        MapSyncEndpoints<SyncOrderEntity, int>(group, "SyncOrder");
        MapSyncEndpoints<SyncOrderLineEntity, int>(group, "SyncOrderLine");

        return group;
    }

    /// <summary>Maps the sync-only endpoints of one synchronised table onto the group.</summary>
    /// <remarks>
    /// <para>
    /// They exist because the remote surface deliberately has no <c>Query()</c>: a differential pass needs rows above a
    /// version, the version ceiling of the pass, and the key set of the table, and none of those can be expressed
    /// through CRUD. Uploading needs nothing new - a replayed change is an ordinary Insert, Update, Save, or Delete, and
    /// travels over the endpoints that already exist, conflict reporting included.
    /// </para>
    /// <para>
    /// The handlers are a thin remoting of <c>ISyncServerSource&lt;,&gt;</c>, which the server resolves from DI
    /// (<c>AddGeneratedDirectSyncSources</c>): the answers a remote client gets are produced by the same source a
    /// co-located client would call directly, so there is one implementation of the semantics rather than two.
    /// </para>
    /// <para>
    /// Nothing is remembered between requests. The resume point arrives as the anchor and the bound as the ceiling, so
    /// two clients syncing the same table do not interfere and an interrupted run resumes by asking again. The flip side
    /// is that the ceiling is the caller's value: a client that sends one above the server's own lowest active version
    /// skips whatever is still in flight below it for good, which is why the ceiling endpoint exists and its answer is
    /// what a client is expected to send back.
    /// </para>
    /// <para>
    /// They are members of the group like every other endpoint, so authorization applied to the group covers them - and
    /// it has to: the changed-rows endpoint hands out whole rows and honors the batch size the caller asks for, and the
    /// key endpoint hands out an entire table's key set in one response.
    /// </para>
    /// </remarks>
    private static void MapSyncEndpoints<TEntity, TKey>(RouteGroupBuilder group, string entityRoute)
        where TEntity : EntityBase, new()
    {
        group.MapPost(
            $"{entityRoute}/{RemoteSyncOperations.Ceiling}",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteAsync(
                    context,
                    async () =>
                        (object?)
                            new RemoteSyncCeilingResult(
                                await SyncSource<TEntity, TKey>(context)
                                    .GetChangeCeilingAsync(context.RequestAborted).ConfigureAwait(false)
                            )
                )
        );
        group.MapPost(
            $"{entityRoute}/{RemoteSyncOperations.Changes}",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await RemoteServerEngine.ReadRequestAsync<RemoteSyncChangesRequest>(
                            context
                        ).ConfigureAwait(false);
                        var batch = await SyncSource<TEntity, TKey>(context)
                            .GetChangesAsync(
                                request.Anchor,
                                request.Ceiling,
                                ValidatedBatchSize(request.BatchSize),
                                context.RequestAborted
                            ).ConfigureAwait(false);
                        return (object?)
                            new RemoteSyncChangesResult<TEntity>(batch.Rows, batch.HasMore);
                    }
                )
        );
        group.MapPost(
            $"{entityRoute}/{RemoteSyncOperations.Keys}",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteAsync(
                    context,
                    async () =>
                        (object?)
                            new RemoteSyncKeysResult<TKey>(
                                await SyncSource<TEntity, TKey>(context)
                                    .GetAllKeysAsync(context.RequestAborted).ConfigureAwait(false)
                            )
                )
        );
    }

    /// <summary>Resolves the differential source the sync endpoints answer from.</summary>
    private static ISyncServerSource<TEntity, TKey> SyncSource<TEntity, TKey>(HttpContext context)
        where TEntity : EntityBase, new() =>
        context.RequestServices.GetRequiredService<ISyncServerSource<TEntity, TKey>>();

    /// <summary>Validates the batch size carried by a request body (a non-positive value is reported to the client as HTTP 400).</summary>
    /// <remarks>
    /// The generated client never sends one - its own engine rejects it first - but the number arrives from the wire and
    /// a value of zero or less has no meaning the server could act on: it would either return nothing forever or reach
    /// the database as a malformed limit, therefore it is rejected here as a fault in the payload the client sent. There
    /// is deliberately no upper bound: the caller chooses how much it wants per round trip, and what keeps that from
    /// being abused is the authorization on the group rather than a number chosen here.
    /// </remarks>
    private static int ValidatedBatchSize(int batchSize) =>
        batchSize > 0
            ? batchSize
            : throw new RemoteBadRequestException("The batch size must be greater than zero.");

    /// <summary>Invokes the <c>OnServerError</c> extension hook while isolating any failure inside it.</summary>
    /// <remarks>
    /// The hook is user code and runs before the 500 body (<see cref="RemoteError"/>) has been written, so an exception
    /// escaping from it would discard the original error response and leave the client with a generic failure whose
    /// cause is lost. The hook must never replace the original failure, therefore an exception thrown by it is
    /// reported through the same server-side logging and then swallowed. This wrapper is what the engine receives as
    /// the group's hook, because a partial method has no callable form outside the part that declares it.
    /// </remarks>
    private static void RaiseServerError(HttpContext context, Exception ex)
    {
        try
        {
            OnServerError(context, ex);
        }
        catch (Exception hookError)
        {
            RemoteServerEngine.LogServerError(context, hookError);
        }
    }

    /// <summary>Extension hook invoked - after the built-in logging - whenever an endpoint responds with HTTP 500.</summary>
    /// <remarks>
    /// Implement this method in another part of this partial class to add custom handling for server-side
    /// failures (notifications, metrics, extra logging). It is reserved for HTTP 500 and is therefore not invoked for
    /// classified responses (400 and 409). When no implementation is provided the compiler removes
    /// the call itself, so nothing but an empty guard remains. An exception thrown by the hook is isolated (logged
    /// on the server side and then swallowed) and never replaces the original 500 response. The hook always receives the
    /// exception itself, whether or not the endpoint exposes error details to the client. The 500 response body
    /// itself is not customizable here; wrap the group returned by <c>MapGeneratedRemoteEndpoints</c> in middleware
    /// to translate responses instead.
    /// </remarks>
    /// <param name="context">The HTTP context of the failed request.</param>
    /// <param name="ex">The unhandled exception that was reported to the client.</param>
    static partial void OnServerError(HttpContext context, Exception ex);

    /// <summary>Maps the remote-surface endpoints for SyncOrderEntity.</summary>
    private static void MapSyncOrderEndpoints(RouteGroupBuilder group, bool allowUnboundedUploads)
    {
        RemoteServerEngine.MapCrud<SyncOrderEntity, int, ISyncOrderRemoteRepository>(
            group,
            "SyncOrder"
        );

        group.MapPost(
            "SyncOrder/CheckUniqueness",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await RemoteServerEngine.ReadRequestAsync<SyncOrderCheckUniquenessRequest>(context).ConfigureAwait(false);
                        var repository = RemoteServerEngine.Repository<ISyncOrderRemoteRepository>(context);
                        return (object?)await repository.CheckUniquenessAsync(RemoteServerEngine.Required(request.Entity, "Entity"), context.RequestAborted).ConfigureAwait(false);
                    }
                )
        );

        group.MapGet(
            "SyncOrder/Attachment",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteDownloadAsync(
                    context,
                    destination =>
                    {
                        var repository = RemoteServerEngine.Repository<ISyncOrderRemoteRepository>(context);
                        return repository.ReadAttachmentAsync(
                            RemoteServerEngine.ParseKeyFromQuery<int>(context),
                            destination,
                            context.RequestAborted
                        );
                    }
                )
        );

        var uploadAttachment = group.MapPut(
            "SyncOrder/Attachment",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteUploadAsync(
                    context,
                    (body, length) =>
                    {
                        var repository = RemoteServerEngine.Repository<ISyncOrderRemoteRepository>(context);
                        return repository.WriteAttachmentAsync(
                            RemoteServerEngine.ParseKeyFromQuery<int>(context),
                            body,
                            length,
                            context.RequestAborted
                        );
                    }
                )
        );

        if (allowUnboundedUploads)
        {
            uploadAttachment.WithMetadata(DisableRequestBodySizeLimit.Instance);
        }

        group.MapDelete(
            "SyncOrder/Attachment",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteDeleteAsync(
                    context,
                    () =>
                    {
                        var repository = RemoteServerEngine.Repository<ISyncOrderRemoteRepository>(context);
                        return repository.WriteAttachmentAsync(
                            RemoteServerEngine.ParseKeyFromQuery<int>(context),
                            null,
                            null,
                            context.RequestAborted
                        );
                    }
                )
        );
    }

    /// <summary>Request body for CheckUniqueness (SyncOrder).</summary>
    private sealed record SyncOrderCheckUniquenessRequest(SyncOrderEntity Entity);

    /// <summary>Maps the remote-surface endpoints for SyncOrderLineEntity.</summary>
    private static void MapSyncOrderLineEndpoints(RouteGroupBuilder group)
    {
        RemoteServerEngine.MapCrud<SyncOrderLineEntity, int, ISyncOrderLineRemoteRepository>(
            group,
            "SyncOrderLine"
        );

        group.MapPost(
            "SyncOrderLine/CheckUniqueness",
            (HttpContext context) =>
                RemoteServerEngine.ExecuteAsync(
                    context,
                    async () =>
                    {
                        var request = await RemoteServerEngine.ReadRequestAsync<SyncOrderLineCheckUniquenessRequest>(context).ConfigureAwait(false);
                        var repository = RemoteServerEngine.Repository<ISyncOrderLineRemoteRepository>(context);
                        return (object?)await repository.CheckUniquenessAsync(RemoteServerEngine.Required(request.Entity, "Entity"), context.RequestAborted).ConfigureAwait(false);
                    }
                )
        );
    }

    /// <summary>Request body for CheckUniqueness (SyncOrderLine).</summary>
    private sealed record SyncOrderLineCheckUniquenessRequest(SyncOrderLineEntity Entity);
}
